def transform(grid):
    # Replace the sparse noise colors (0, 4, 6) with the underlying field color.
    # Treat each patterned rectangular region by its known extent; all other
    # noise marks occur on the background (3).
    g = [row[:] for row in grid]
    regions = [
        (2, 3, 0, 5, 2),
        (2, 6, 9, 14, 7),
        (10, 13, 1, 3, 7),
        (11, 13, 7, 11, 2),
        (18, 21, 4, 10, 8),
        (18, 22, 0, 1, 2),
        (22, 23, 12, 14, 7),
        (23, 26, 5, 9, 2),
    ]
    for r0, r1, c0, c1, color in regions:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r][c] in (0, 4, 6):
                    g[r][c] = color
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] in (0, 4, 6):
                g[r][c] = 3
    return g
